    bg:  "<div class=\"bg\" aria-hidden=\"true\">\n    <div class=\"glow g1\"></div><div class=\"glow g2\"></div><div class=\"glow g3\"></div>\n    <div class=\"dots d1\"></div><div class=\"dots d2\"></div>\n  </div>",
